from dataclasses import dataclass


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: "Expr"
    r: "Expr"


@dataclass
class Mul:
    l: "Expr"
    r: "Expr"


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an expression tree of Num, Add, and Mul nodes to an int."""
    match e:
        case Num(v=v):
            return v
        case Add(l=l, r=r):
            return eval_expr(l) + eval_expr(r)
        case Mul(l=l, r=r):
            return eval_expr(l) * eval_expr(r)
        case _:
            raise TypeError(f"unknown expression node: {e!r}")


def test_num() -> None:
    assert eval_expr(Num(7)) == 7


def test_negative_num() -> None:
    assert eval_expr(Num(-3)) == -3


def test_add() -> None:
    assert eval_expr(Add(Num(2), Num(3))) == 5


def test_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(5))) == 20


def test_nested_add_mul() -> None:
    e = Add(Mul(Num(2), Num(3)), Num(4))
    assert eval_expr(e) == 10


def test_mul_of_sums() -> None:
    e = Mul(Add(Num(1), Num(2)), Add(Num(3), Num(4)))
    assert eval_expr(e) == 21


def test_deep_left_chain() -> None:
    e: Expr = Num(1)
    for _ in range(50):
        e = Add(e, Num(1))
    assert eval_expr(e) == 51
